def localize_notification_messages(apps, schema_editor):
    Notification = apps.get_model('notifications', 'Notification')
    status_labels = {
        'To Do': 'Chưa thực hiện',
        'In Progress': 'Đang thực hiện',
        'Completed': 'Đã hoàn thành',
        'On Hold': 'Tạm dừng',
    }
    for notification in Notification.objects.all().iterator():
        message = notification.message
        if message.startswith('Deadline ') and message.endswith(' đang đến gần.'):
            task_title = message[len('Deadline '):-len(' đang đến gần.')]
            message = f'Công việc "{task_title}" sắp đến hạn.'
        elif message.startswith('Công việc "') and '" có hạn ' in message:
            message = message.replace('" có hạn ', '" sắp đến hạn vào ngày ', 1)
        else:
            for old_status, new_status in status_labels.items():
                suffix = f' chuyển sang {old_status}.'
                if message.endswith(suffix):
                    message = f'{message[:-len(suffix)]} đã chuyển sang trạng thái {new_status}.'
                    break
        if message != notification.message:
            notification.message = message
            notification.save(update_fields=['message'])


